package api;

import config.ConfigReader;
import io.restassured.builder.RequestSpecBuilder;
import io.restassured.specification.RequestSpecification;

/**
 * Shared RestAssured setup for every Paytm Checkout API call.
 * Base URL and frontend-build-version come from config.properties.
 */
public class ApiRequestSpec {

    public static String getBaseUrl() {
        return ConfigReader.getBaseUrl();
    }

    public static RequestSpecification commonSpec() {
        String baseUrl = getBaseUrl();
        return new RequestSpecBuilder()
                .setBaseUri(baseUrl)
                .setRelaxedHTTPSValidation()
                .addHeader("Accept", "application/json")
                .addHeader("Content-Type", "application/json")
                .addHeader("Origin", baseUrl)
                .addHeader("frontend-build-version", ConfigReader.getFrontendBuildVersion())
                .build();
    }
}

package api;

import io.restassured.RestAssured;
import io.restassured.response.Response;
import pojo.request.CartRequest;
import pojo.request.ConfirmationCartRequest;

public class CartApi {

    public Response viewCart(String code, String sessionToken, CartRequest request) {
        return ApiCall.retry(() -> RestAssured
                .given()
                .spec(ApiRequestSpec.commonSpec())
                .header("Referer", ApiRequestSpec.getBaseUrl() + "/qr_menu/cart/")
                .header("session-token", sessionToken)
                .body(request)
                .when()
                .post("/qr_view_cart/" + code)
                .then()
                .extract()
                .response());
    }

    /**
     * After-payment confirmation page. ct comes from the Telr return URL.
     * Do not store MQTT / AWS tokens from this payload.
     */
    public Response viewCustomerCart(
            String code,
            String sessionToken,
            String ct,
            ConfirmationCartRequest request
    ) {

        return ApiCall.retry(() -> RestAssured
                .given()
                .spec(ApiRequestSpec.commonSpec())
                .header("Referer", ApiRequestSpec.getBaseUrl() + "/qr_menu/paybill/?ct=" + ct)
                .header("session-token", sessionToken)
                .queryParam("view", "customer")
                .queryParam("ct", ct)
                .body(request)
                .when()
                .post("/qr_view_cart/" + code + ".json")
                .then()
                .extract()
                .response());
    }
}

package api;

import io.restassured.RestAssured;
import io.restassured.response.Response;
import pojo.request.PaymentRequest;

public class PaymentApi {

    public Response initiatePayment(String code, String sessionToken, PaymentRequest request) {

        return ApiCall.retry(() -> RestAssured
                .given()
                .spec(ApiRequestSpec.commonSpec())
                .header("Referer", ApiRequestSpec.getBaseUrl() + "/qr_menu/cart/")
                .header("session-token", sessionToken)
                .body(request)
                .when()
                .post("/initiate_payment/" + code)
                .then()
                .extract()
                .response());
    }

    /**
     * Polls order/payment result after Telr redirects back.
     * ct is a query param on the Paytm return URL, not a field from initiate_payment.
     */
    public Response fetchPaymentStatus(String code, String sessionToken, String ct) {

        return ApiCall.retry(() -> RestAssured
                .given()
                .spec(ApiRequestSpec.commonSpec())
                .header("Referer", ApiRequestSpec.getBaseUrl() + "/qr_menu/paybill/?ct=" + ct)
                .header("session-token", sessionToken)
                .queryParam("ct", ct)
                .when()
                .get("/fetch_payment_status_by_session_id/" + code)
                .then()
                .extract()
                .response());
    }
}

