        CheckoutResult checkout = CheckoutFlow.payAndConfirm(token, paymentRequest);
        CheckoutFlow.assertOrderMatchesCart(cart, checkout.confirmation());
        CheckoutFlow.assertOmsCustomer(checkout, name);

